mapper.select:
SELECT ci.cart_item_id, p.product_id, p.name AS product_name, p.author, p.publisher, pi.image_path, p.price, ci.quantity, p.stock_quantity FROM cart_item ci JOIN cart c ON ci.cart_id = c.cart_id JOIN product p ON ci.product_id = p.product_id LEFT JOIN product_image pi ON p.product_id = pi.product_id AND pi.image_type = 'THUMBNAIL' WHERE c.member_id = #{memberId} AND ci.cart_item_id IN
#{cartItemId}
AND p.deleted_at IS NULL AND p.status = 'ACTIVE'

mapper.update:
UPDATE product
SET status = CASE
        WHEN stock_quantity - #{quantity} = 0 THEN 'SOLD_OUT'
        ELSE status
    END,
    stock_quantity = stock_quantity - #{quantity}
WHERE product_id = #{productId}
AND deleted_at IS NULL
AND status = 'ACTIVE'
AND stock_quantity >= #{quantity}
